export const HERO = {"eyebrow": "The system, shown working", "title": "Everything that moves, and exactly why it does", "lede": "A portfolio that ships its own design system in the open: three view modes, two themes, a stepped clock, and forty-two figures that play only when you scroll to them. No black boxes, no mystery meat. Every token has a job, every beat has one idea, and every animation tells the truth about the product. Read the source the way you would read the credits: it is all here, and none of it is decoration."};

export const ASIDES = {"Read Mode": "The default, chronological stack: like scrolling a feed that respects your attention instead of farming it.", "Scan Mode": "A nan.fyi-style grid where hovering one tile dims the rest to 0.4: spotlight on, house lights down.", "Present Mode": "Hit play and the case study becomes a deck. Esc drops you back to earth, Inception-style kick.", "Motion Lab": "An unlisted /lab route with no nav link: the warp zone you only find if you know the pipe.", "Theme Toggle Animation": "A Lucide sun whose crescent bite slides in eight px to become a moon. Total eclipse, on click.", "Persistent Theme State": "flushSync sets the dark class before the snapshot, then localStorage remembers your side forever after.", "Accent Color System": "One --accent per case study, color-mixed at 34 percent: every project gets its own house color.", "Sliding Thumb (Selection Indicator)": "Mid-switch it goes glass: 45 percent opacity, blur six, scale 1.07 at the 42 percent keyframe, then settles.", "Play Button (Present Mode)": "It waits off-stage at translateX -170 percent until the toggle exits right. Patience, then the cue.", "fig (coded figures)": "Live React SVG, rebuilt every time, auto-playing on view: not a gif of the product, the product.", "design (Design Mode)": "A pixel-perfect Figma plate with shader regions screen-blended on top. Deepfake the UI, honestly.", "reel (Presentation Mode)": "One phone, a camera that zooms and focuses: a Steadicam shot for a single screen.", "awDeepSearch": "The two-minute negotiation as a live timeline, not a spinner: showing the work, like a chef plating in view.", "awSmartPin": "A WhatsApp-style pin that follows trip state, pointing at what matters now: the agent's pinned message to you.", "awVet": "A list that never changes shape, sorted by right not cheapest: vetted, not dumped, with the trap flagged.", "schedSinglePage": "Tap into Late Night, pick 3 to 4 AM, and Tomorrow quietly relabels it Early Morning. Same slot, new name.", "schedSplit": "One cart, up to four hubs, four shipments scheduling on their own: the Avengers-assemble of grocery logistics.", "schedImpact": "AOV counts up 300 to 620 on a rail while the phone holds the booked order: roughly 2x, shown not claimed.", "stellaSim": "Play the call from the candidate side: every reply is a real case from the field log, including the ones that broke the system.", "figmaToCode": "Figma frame beside React, visual-diff score climbing to 100: the design system that wrote its own code.", "agentWizardFff": "Five beats narrow 480 candidates to 42, ranked live: a hiring montage with exactly one thing lit per frame.", "FFF core rule: one-coloured-event": "Exactly one non-gray element per frozen frame. There can be only one, and the critique enforces it.", "useStepSequence clock (12a shared grammar #1)": "Lead 850, beat 600, hold 3000, loop: one metronome every figure dances to, no per-figure timing logic.", "Extract archetype (unstructured → structured)": "A messy eleven-constraint brief untangles into clean rows: AwIntakeBrief turns word soup into a spec sheet.", "useFitScale (scale frame to container)": "Out-of-flow frame so ResizeObserver never eats itself: learned the hard way that an in-flow item shrinks every tick.", "useInViewLoop (play on scroll into view)": "IntersectionObserver at 0.35 gates the whole show: off-screen figures sleep, like NPCs outside the render distance.", "Cursor.jsx (demo pointer + ripple)": "A soft dark halo with an accent ripple, allowed only in scaffold mode: the one ghost cleared to touch the UI.", "Spatial tokens (movement/scale)": "cubic-bezier(0.38,1.21,0.22,1), y over one: the overshoot you reserve for the pop that earns it.", "Brand accent carrier": "dassh #EA580C marks only the result, blue works and green is done, never both in one frame.", "Corner-shape: squircle (iOS superellipse)": "corner-shape: squircle on the universal selector: every radius curves like Figma 60, no exceptions, no per-element overrides.", "Newsreader serif for emphasis": "A screen-reading serif in TLDRs and scan titles: the site clearing its throat to say this part is editorial.", "No tilde (about ) or em-dash (, ) in any copy": "The one house rule with teeth: punctuation is brand, and these two never make the cut.", "buildSlides()": "Hand-authored deck if you wrote one, else one slide per section: the director's cut or the autoplay, your call.", "figma-fidelity (SVG mode)": "resvg renders SVG to PNG and NumPy diffs it against Figma, no browser: a robot spot-the-difference, until it scores.", "Shimmer freeze during beat": "Background shimmer halts so the focal motion stands alone: bullet-time, but for a skeleton that knows to hold still.", "Caption chip (concept namer)": "A 28px dark chip that names the beat and nothing else: the lower-third caption that replaced the whole popup."};

