export const FFF = [{"name": "FFF core rule: one-coloured-event", "what": "At any frozen instant exactly ONE element is non-gray/non-shimmer, the concept of that beat. Everything else is skeleton or muted. Competing colors = frame failure.", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Claude/animation-base-layer.md §11", "detail": "Enforced by design: before animation, hand-author the frame so only one element/region 'pops' (lights color). If a still shows two coloured things, adversarial critique forces cut/merge. This is the whole editorial power of FFF, one idea at a time.", "kind": "framework"}, {"name": "FocalOutline (blue/green/amber/red/area)", "what": "The lit element of a beat: 2px solid border, 4px shadow halo, 9px radius. Parent positions via style {left,top,width,height}. Animates dsFocalIn (scale 0.96→1, 180ms Expressive).", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Scaffold.jsx lines 119–121; scaffold.css lines 63–70", "detail": "Variants: --ds-focal-blue #3b82f6 (active/working), --ds-focal-green #22c55e (set/done), --ds-focal-amber #f59e0b (attention), --ds-focal-red #ef4444 (broken), area (dashed, fill 9% opacity). In SystemExplainer, blue is the default 'on' marker.", "kind": "component"}, {"name": "Caption chip (concept namer)", "what": "Small plain label chip (28px height, inline-flex, dark bg, white text, dot indicator). Names the concept, replaces the annotation popup entirely.", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Scaffold.jsx lines 124–126; scaffold.css lines 72–78", "detail": "Data-mode='blue'|'green'|'amber'|'red' changes --ds-caption__dot background. No Cancel/Add buttons; no field caret. The Caption IS the concept label, brevity enforces clarity. Shadow 0 10px 26px, radius 8px, padding 0 13px.", "kind": "component"}, {"name": "Shimmer freeze during beat", "what": "While a focal element animates, freeze the background shimmer (animation: none !important) so the focal motion stands alone against a calm surface.", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/scaffold.css lines 60–61 (.ds-shim--freeze)", "detail": "CSS-based; parent can toggle .ds-shim--freeze on the Shimmer blocks. Means 'this beat, no breathing, let the focal element be the only motion.' Choreography handles class toggle per step.", "kind": "technique"}, {"name": "Stella onboarding (first FFF build)", "what": "A skeleton checklist that completes itself (green checks, no forms, no cursor). Showcases FFF framework: one check stamps at a time, rest shimmer, Caption names each task.", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/onboarding/StellaOnboarding.jsx", "detail": "Designed via multi-lens workflow + adversarial critique. Critique forced cutting the cursor-click and the popup, both were 'still animating the UI.' Result: pure state-arrival animation (concept lights, holds, loops). Reduced motion seeds step=N (all done), no clock.", "kind": "implementation"}];

