export const TOKEN_FAMILIES = [{"name":"Dark theme","what":"A full dark token set, opted into with data-theme=\"dark\" on the .ds-root","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"An extension, not a transcription of the light product: warm-neutral dark surfaces (never pure black, which would break the border-only depth language), the same four-step text hierarchy inverted, and every product hue lifted for contrast. Borders run a step brighter relative to surface because depth comes from them, not shadows. Component CSS reads identical token names in both themes.","kind":"token family"}, {"name":"Voice-agent tones","what":"Four concerns a spoken turn can be annotated against, mapped onto the existing product palette","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"--ds-tone-register (Brand purple, language), --ds-tone-numbers (Forest Teal, data accuracy), --ds-tone-repair (accent, error recovery), --ds-tone-trust (Mystic Blue, consent). Each has a -bg pair. Components read them via [data-tone] so a consumer cannot drift off-palette.","kind":"token family"}, {"name": "Surfaces", "what": "App canvas, cards, inputs, and muted chip backgrounds", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:13-17", "detail": "--ds-bg (#fbfaf7), --ds-surface (#ffffff), --ds-field (#fdfdfd), --ds-muted (#f5f5f5) form the visual hierarchy with warm canvas + bright surfaces", "kind": "token family"}, {"name": "Borders & Lines", "what": "Default borders (inputs/buttons/tabs), card edges, hairlines, brand accent, active states", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:19-24", "detail": "--ds-border-card (0.5px thinness in source), --ds-tab-active (2px #303030 underline), --ds-border-brand (#f4ebff prompt input) preserve Dassh's border-only depth language", "kind": "token family"}, {"name": "Text Colours", "what": "Body text, labels, subtitles, placeholders, tertiary text", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:26-33", "detail": "--ds-text (#181d27 Gray/900 primary), --ds-text-2 (#717680 Gray/500 subtitles), --ds-text-3 (#b3b3b3 tertiary empty-slot text)", "kind": "token family"}, {"name": "Focal Colours (FFF)", "what": "One-lit-element-per-beat annotation system: blue (active), green (completed), amber (decision pending), red (broken)", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:66-75", "detail": "--ds-focal-blue (#3b82f6), --ds-focal-green (#22c55e), --ds-focal-amber (#f59e0b), --ds-focal-red (#ef4444) each with 0.09-0.11 alpha fills; --ds-focal-w (2px ring), --ds-focal-r (9px radius hugs skeleton)", "kind": "token family"}, {"name": "Primary Button", "what": "Black button palette: default, pressed, on-primary text, soft surface", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:35-40", "detail": "--ds-primary (#1e1e1e), --ds-primary-press (#000000), --ds-on-primary-soft (#f3f3f3) for disabled/hover states", "kind": "token family"}, {"name": "Success & Brand", "what": "Green system (Essential text, import-bar), purple brand (prompt banner), orange accent (cursor ripple only)", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:42-55", "detail": "--ds-green (#039855 Success/600), --ds-purple (#42307d Brand/900), --ds-accent (#ea580c confined to demo cursor click ripple, NOT source UI", "kind": "token family"}, {"name": "Scaffold (Shimmer + Annotation)", "what": "Skeleton blocks and dark annotation popup theming for information-sensitive preset", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:57-64", "detail": "--ds-shim (#e7e9ed skeleton fill), --ds-popup (#1f1f22 dark bg), --ds-popup-field (#2c2c30), --ds-popup-text (#f3f3f3), --ds-popup-muted (#9aa0a8)", "kind": "token family"}, {"name": "Control Fills", "what": "Toggle off, slider rail, fill states", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:86-90", "detail": "--ds-toggle-off (#d5d7da), --ds-slider-rail (#d9d9d9), --ds-slider-fill (#1e1e1e) match primary button", "kind": "token family"}, {"name": "Typography & Spacing", "what": "Compact type scale (13px app title to 9px meta) and 4/6/8/10/12/14/18px spacing rhythm", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:92-108", "detail": "Inter/-apple-system sans-serif; --ds-fs-app (13px), --ds-fs-title (15px), --ds-fs-body (11.5px), --ds-fs-meta (9px); --ds-1 (4px) to --ds-7 (18px) preserve source's 4/8/12/16/24 rhythm at compact scale", "kind": "token family"}, {"name": "Motion & Shape", "what": "Material Design 3 easing (standard/decelerate/accelerate/expressive), durations (100–500ms), M3 corner scale mapped to figure radii", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css:110-149", "detail": "--ds-ease-out (decelerate enter/expand), --ds-ease-pop (expressive press), --ds-dur-move (500ms M3-long2), --ds-r-frame (16px), --ds-r-card (12px), --ds-r-btn (8px)", "kind": "token family"}];

export const PRIMITIVES = [{"name":"PlanQueue","what":"The work an agent still intends to do, and what the running loop did to it","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"status: todo | done | struck | added. struck is load-bearing: a step removed because the agent LEARNED it does not apply. An open-loop script has no interesting plan state, because nothing it hears can change what it does next.","kind":"component"}, {"name":"Caught","what":"What a background listener heard, attached to the line it heard it in","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"which: intent | distress | comprehension | escalation. Replaces a rail of lamps: a rail says a system is watching, this says what it caught, here, in this sentence.","kind":"component"}, {"name":"Disposition","what":"How something closed, and whether the system label for it was true","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"truthful={false} shows the label a system actually wrote beside the evidence that it was wrong. Quietly correcting the label would lose the argument.","kind":"component"}, {"name":"useMediaQuery","what":"A live media query in JS, for controls that must know a panel is hidden","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/hooks.js","detail":"CSS cannot set aria-disabled, so a control whose panel a media query has hidden cannot say so from CSS alone. Stella's Operator toggle stayed live and reported aria-pressed=true below 1100px, where the column it reveals is display:none.","kind":"component"}, {"name":"--ds-font-gu (Anek Gujarati)","what":"The Indic face, self-hosted, by Ek Type","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"Anek Gujarati (OFL-1.1) via @fontsource-variable/anek-gujarati, imported at the top of tokens.css so the DS declares its own faces. Replaces a fallback stack that rendered differently on every machine (Gujarati Sangam MN on a Mac, Nirmala UI on Windows, Noto on Linux) inside a box authored for Inter. Critically the package ships a LATIN COMPANION UNDER THE SAME FAMILY with a unicode-range per subset, so a code-mixed line like \"Zydus na Sanand plant ma interview chhe\" keeps one skeleton across both scripts instead of switching to Inter mid-sentence. Variable wght 100-800. Used by .stl__guj, .cand__guj and both transliteration rules: a transliteration belongs to the line it romanises, while the English gloss stays on Inter because it is the meaning, in the product voice.","kind":"token"}, {"name":"--ds-tone-*-ink","what":"The text value of a tone, distinct from its fill","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"Fills are brand hues and stay as they are; as TEXT they measured 3.2 to 3.9:1 on white and on their own tints, so 7 of 14 light pairs failed 4.5:1. Dark was already 7.35 to 9.02:1, which is why it went unnoticed: the tones were mapped onto the product palette and the light theme was never re-measured. qaStella computes all 24 pairs.","kind":"token"}, {"name":"--ds-focus-ring","what":"One keyboard focus indicator for the whole system","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"There was no focus style anywhere in the DS, and `outline: none` appeared twice as the only focus declarations in either stylesheet. --ds-tone-trust is 3.93:1 on white and 7.96:1 on the dark surface, so one token clears the 3:1 non-text floor in both themes. Paired with .ds-root--live :focus-visible so no consumer invents its own.","kind":"token"}, {"name":"--ds-border-control","what":"A boundary a person clicks, split from a divider","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/tokens.css","detail":"3.06:1 on --ds-field in light, 3.03:1 in dark. --ds-border was 1.39:1 and --ds-line measurably got WORSE in dark (1.23:1), which falsified the DS README's own claim that dark borders sit a step brighter relative to their surface. WCAG 2.1 SC 1.4.11, not an HIG number: the HIG's only contrast table is text.","kind":"token"}, {"name":"useDsTheme","what":"Resolve a DS surface's theme from the site, never assert it","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/hooks.js","detail":"Reads the dark/light class the site already sets on documentElement, falls back to prefers-color-scheme, stays reactive to both via MutationObserver plus a matchMedia listener. Before this every ds-root asserted its own theme, so the authored light tokens were unreachable: a visitor reading the site in light got a dark console, and the PDF export path (which forces theme=light) printed a dark island in a light document. There is deliberately no in-app appearance toggle in this system.","kind":"component"}, {"name":".ds-panetitle","what":"Level one of a three-level pane hierarchy","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/components.css","detail":"Pane title, then uppercase subsection head, then disclosure summary. A pane that gives all three the same treatment ranks nothing and the eye has no entry point. Sentence case at section size on full-strength ink, so it outranks a micro-label by weight and size rather than by being louder in the same register.","kind":"component"}, {"name":".ds-bubblerow","what":"A conversation turn plus controls that cannot live inside it","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/components.css","detail":"Bubble's `actions` slot renders here, as a SIBLING of the bubble. With as=\"button\" the whole turn is one button and a button may not contain another, so a per-turn control (replay, copy, flag) has nowhere legal to go inside it.","kind":"component"}, {"name": "StepRail", "what": "The states-rail beside a phone, promoted out of two identical copies", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/StepRail.jsx", "detail": "Props: {prefix, cap, steps, active, done, defaultTone}. This existed TWICE (scheduled/Rail.jsx and awayAgent/Rail.jsx); after normalising the class prefix the two differed in exactly ONE substantive line, the default tone, and ten figures import one or the other, so a change to the rail's structure had to be made twice and would reliably be made once. What is shared is the STRUCTURE; the skin is not, because these are two case studies with deliberately different visual languages (Scheduled light on purple at 16px radius, Away dark on indigo at 12px). Hence the prefix prop, which a design system should not normally take: it is right here because the duplication was structural and the divergence is intentional. Both Rail.jsx files are now one-line adapters.", "kind": "component"}, {"name": "IconCheck", "what": "The plain check glyph the design system did not own", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx", "detail": "Every rail needs a check and the DS had none, so both figure families shipped a byte-identical copy in their own icons.jsx. Both now re-export this one, which collapses the duplicates without touching the ~12 call sites that import ICheck. Same stroke props as the rest of the line set.", "kind": "component"}, {"name": "Button", "what": "The button the system did not have: one chassis, five variants, four sizes", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx", "detail": "Props: {variant: quiet|outline|filled|tone|icon, size: sm 28|md 30|lg 34|auto, tone, block, className}. Replaces FOURTEEN hand-rolled button rule groups in Stella alone: four heights, three different border tokens, and two byte-identical duplicates (.cand__back was a copy of .ats__back). The cost was already paid before this existed: the press-state rule in components.css was a hand-typed allowlist of figure-private class names and four real buttons were missing from it, so they had no press feedback at all; a second copy of that list lived in qaStella. Only the CHASSIS is shared. A figure keeps its own class where the control carries a surface-specific argument (.stl__choice reveals a failure tag on hover, .stl__mode has a dashed aria-disabled state naming its reason), composing a thin layer over this base. variant=tone reads the scale via [data-tone] and takes the -ink pair for text, so no consumer names a hue. Safe to promote where Tabs was not: one button ships the complete native keyboard model.", "kind": "component"}, {"name": "GhostInput", "what": "A composer that completes the caller's own vocabulary inline, Claude-style", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx", "detail": "Props: {value, onChange, onSubmit, suggestions, placeholder, ariaLabel, hint}. A mirror element renders the ghost behind a transparent input, so both must declare their type metrics in ONE css rule or the completion stops sitting flush against the typed text. ArrowRight and Tab accept only when the caret is at the END: stealing them mid-text would break the one behaviour every other input has. Escape dismisses. The suggestions carry an obligation the component cannot enforce: each must be something the receiving surface will actually accept, since completing someone into a request that then gets refused is worse than not completing at all.", "kind": "component"}, {"name":"Disclosure","what":"Progressive disclosure for the evidence behind a claim, not for anything needed to act","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Props: {label, meta, open, children}. A real <details>: works with find-in-page and without JavaScript, and the summary stays on screen when closed so the label is a promise that something is under it. Tabs vs disclosure is a question about SIMULTANEITY, not density: tabs make panes mutually exclusive, a disclosure only makes them unequal. So alternatives get tabbed, but a pane that is the EVIDENCE for a claim made in another pane must never be, because a reader who has to click to check is being asked to take the first pane on faith. Two side by side is therefore correct when one leads at full weight: rank by weight, not by visibility.","kind":"component"}, {"name":"ScopeNote","what":"A standing statement of what is real in a demonstration","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"No dismiss control by design: a scope note you can close is a scope note that will be absent exactly when someone forms the wrong impression.","kind":"component"}, {"name":"Verdict","what":"An agent's recommendation, put to the human who owns the decision","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Props: {tone, label, headline, because[], unsure[], children}. because and unsure are required shapes, not decoration: the recommendation never appears without its reasoning, and what the agent could NOT establish gets equal billing. Children slot in the override, which is expected to sit at the same weight as the agreement. A recommendation with no visible way to disagree is a decision wearing a softer word.","kind":"component"}, {"name":"FieldRow","what":"One row of a structured record an agent is filling, with an honest state","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"state: empty | asked | heard | confirmed | na | offscript. asked is kept distinct from heard on purpose, because a record that fills in when a question is merely ASKED is dishonest instrumentation. offscript is dashed: a listener caught it and the form has no column for it.","kind":"component"}, {"name":"Bubble","what":"One conversation turn: speaker label, tone outline, and a speaking state","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Props: {speaker, side (start|end|full), tone, active, speaking, as}. side=full is a system record, not speech. as=\"button\" when the turn is inspectable. Tone read from --ds-tone-* via [data-tone], never hardcoded.","kind":"component"}, {"name":"Pill","what":"Small labelled tag for annotation categories, failure cases and statuses","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Props: {tone, soft}. soft adds the tinted background from --ds-tone-*-bg.","kind":"component"}, {"name":"StatusDot","what":"State dot with a soft halo: live calls, fired listeners, agent health","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Props: {tone, off}. off greys it to --ds-toggle-off and drops the halo.","kind":"component"}, {"name":"Waveform","what":"Three-bar speaking indicator for the turn currently being voiced","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Under prefers-reduced-motion the three bars are REPLACED BY THE WORD (.ds-wave i goes display:none and .ds-wave__word unhides), not frozen: three still bars where a live state was is a decorative shape, not an equivalent. state=\"buffering\" returns a STATIC three-dot mark so a wait never has the same shape as speech.","kind":"component"}, {"name":"SoundToggle","what":"Labelled mute control for any surface that speaks","where":"/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx","detail":"Labelled on purpose: an icon alone does not tell a first-time listener whether sound is currently on. aria-pressed carries the state.","kind":"component"}, {"name": "Icons (line set)", "what": "Compact stroke icons: Chevron, Caret, Eye, Plus, Magic, ArrowR, Database, Expand, Upload, Link, Phone, CheckUser, Chat, Globe, Shield, Help, Bell", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:6-24", "detail": "All use stroke=currentColor with 2px strokeWidth, round linecap/linejoin; aria-hidden on all; IconChevron accepts className prop for styling", "kind": "component"}, {"name": "TopBar", "what": "Chrome: traffic dots (RGB), title text, spacer, Help + Bell icons", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:27-37", "detail": "Uses .ds-top, .ds-dot (R/Y/G), .ds-top__title for styling; mirrors system window chrome", "kind": "component"}, {"name": "StepCard", "what": "Accordion step: numbered head with chevron, optional done checkmark, title/subtitle, body content, footer CTA button", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:41-62", "detail": "Props: {n, title, sub, active, done, press, cta, ctaRef (exposes button node to demo cursor), children}; data-active/data-done/data-press drive CSS states", "kind": "component"}, {"name": "Form Primitives", "what": "Field (label + children wrapper), Input (text display + caret), Textarea, Chip (icon + text), Toggle, Segmented (pills), Slider, Tabs, ChecklistRow", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:65-103", "detail": "Slider shows --ds-fs-meta hint text, --ds-slider__fill width animates via inline style; ChecklistRow composes Segmented for Essential/Valuable/Not Preferred tri-state", "kind": "component"}, {"name": "Composite Blocks", "what": "PromptBanner (Magic icon + input + Generate button), ImportBar (Database icon + count + Import button), DropZone (Link/Upload variant), RestrictionCard (toggle + body)", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:106-138", "detail": "PromptBanner uses ds-prompt__ph placeholder text; ImportBar shows '42 Matching Candidates Found'; DropZone branches on variant prop (connect vs drag-drop)", "kind": "component"}, {"name": "RailStep", "what": "Vertical stepper step: numbered dot (or checkmark), optional connector line, name + optional meta text", "where": "/Users/agamagarwal/My Drive/Active - Portfolio/Portfolio/src/figures/ds/Primitives.jsx:140-153", "detail": "data-state={state} (todo/active/done); dot/line/name all scoped to .ds-rail__* classes; `last` prop hides the connector line", "kind": "component"}];

